import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    t = int(next(iterator))
    MOD = 998244353

    results = []

    for _ in range(t):
        n = int(next(iterator))
        arrays = []
        for _ in range(2 * n):
            row = []
            for _ in range(n):
                row.append(int(next(iterator)))
            arrays.append(tuple(row))

        def is_latin_square(indices):
            mat = [arrays[i] for i in indices]
            for col in range(n):
                vals = {mat[row][col] for row in range(n)}
                if len(vals) != n:
                    return False
            return True

        count = 0
        found_indices = None

        from itertools import combinations

        for combo in combinations(range(2 * n), n):
            if is_latin_square(combo):
                count = (count + 1) % MOD
                if found_indices is None:
                    found_indices = [i + 1 for i in combo]

        results.append(str(count))
        results.append(' '.join(map(str, found_indices)))

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
